window.kbPageData["views/entry/k-545922862610262f"] = {"key":"entry/k-545922862610262f","state":{"route":"entry/k-545922862610262f"},"node":{"id":"k-545922862610262f","mode":"k","title":"司法中的平等适用法律","type":"制度与规则","domain":"法律","reading":"","intro":"","priority":100,"aliases":["司法公正要求平等适用法律"],"qs":["江苏 2023 A类 行测#9"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"司法机关裁判案件时，应以事实和法律为依据，对处于相同法律地位的当事人平等适用法律，不因私人关系或社会身份而偏袒。","review":{"definition":"司法机关裁判案件时，应以事实和法律为依据，对处于相同法律地位的当事人平等适用法律，不因私人关系或社会身份而偏袒。","explanation":"B项的“不别亲疏，不殊贵贱”排除了关系和身份上的偏袒，“一断于法”明确了裁断依据，因而最契合现代司法公正理念。A项着眼于重罚的威慑，C项劝人少争讼，D项谈亲属相隐。","references":[],"evidence":"不别亲疏，不殊贵贱，一断于法","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"江苏 2023 A类 行测#9":{"paper":"江苏 2023 A类 行测","n":9,"mod":"常识判断","src":["22304fe4c340e19d7902.pdf",2],"asrc":["be17f9afe070cf13a0fb.pdf",4],"card":"9fb41f489dbcb70dd23311ec","links":[{"id":"k-545922862610262f","role":"直接考查","why":"古语以亲疏和贵贱为例，表达了对不同当事人一律依法裁断的原则。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-545922862610262f":[["江苏 2023 A类 行测#9"]]}};
